"""Human-facing v0.3 interactive conference dashboard asset."""

DASHBOARD_HTML = r"""<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>CTMAO Agent Conference</title><style>
:root{color-scheme:dark;--bg:#071019;--panel:#101d2a;--panel2:#152739;--ink:#f4f8fb;--muted:#91a5b8;--cyan:#59d7d7;--gold:#f5bd67;--red:#ff8e93;--line:#294056}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 20% -10%,#183b56,var(--bg) 43%);color:var(--ink);font:15px/1.5 system-ui;min-height:100vh}
button,textarea,select{font:inherit}button{cursor:pointer;background:#18334b;color:var(--ink);border:1px solid #3a5b76;border-radius:9px;padding:9px 13px}button.primary{background:#0b7779;border-color:#55d6d6;font-weight:700}button.danger{border-color:#81454d}button:disabled{opacity:.45;cursor:not-allowed}
header{padding:22px max(22px,5vw) 14px;display:flex;justify-content:space-between;gap:18px;align-items:center}.eyebrow{color:var(--cyan);font-weight:700;letter-spacing:.08em;text-transform:uppercase;font-size:12px}h1{margin:2px 0;font-size:clamp(25px,4vw,40px)}h2{margin:0 0 13px;font-size:18px}p{margin:7px 0}.muted{color:var(--muted)}.status{padding:7px 11px;border-radius:999px;background:#163047;color:var(--cyan);white-space:nowrap}
main{max-width:1280px;margin:auto;padding:0 max(22px,5vw) 50px}.panel{background:linear-gradient(145deg,rgba(18,34,49,.97),rgba(12,25,37,.97));border:1px solid var(--line);border-radius:15px;padding:17px;box-shadow:0 14px 40px rgba(0,0,0,.16)}
.composer{display:grid;grid-template-columns:1fr auto;gap:12px;margin-bottom:16px}.composer textarea{min-height:86px;resize:vertical;background:#081622;color:var(--ink);border:1px solid #35536c;border-radius:11px;padding:13px}.composer-actions{display:flex;flex-direction:column;gap:8px;min-width:150px}.error{color:var(--red);min-height:22px;grid-column:1/-1}
.participants{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin-bottom:16px}.participant{position:relative;min-height:135px}.participant.active{border-color:var(--cyan);box-shadow:0 0 0 2px rgba(89,215,215,.15)}.participant-name{font-weight:800;font-size:17px}.participant-role{font-size:13px;color:var(--muted);min-height:39px}.participant-state{color:var(--cyan);font-size:12px;margin:5px 0}.voice-row{display:flex;gap:7px}.voice-row select{min-width:0;flex:1;background:#0a1925;color:var(--ink);border:1px solid #35536c;border-radius:7px;padding:6px}.voice-row button{padding:6px 8px}
.workspace{display:grid;grid-template-columns:minmax(0,2fr) minmax(260px,.72fr);gap:16px}.conversation{min-height:430px;max-height:65vh;overflow:auto;padding-right:5px}.empty{display:grid;place-items:center;min-height:340px;text-align:center;color:var(--muted)}.message{max-width:83%;margin:0 0 15px;padding:13px 15px;border-radius:4px 15px 15px 15px;background:var(--panel2);border:1px solid #2d465c}.message.user{margin-left:auto;border-radius:15px 4px 15px 15px;background:#153e48}.message.decision{border-color:var(--gold);background:#2b261d}.message-head{display:flex;justify-content:space-between;gap:12px;margin-bottom:5px}.speaker{font-weight:800;color:var(--gold)}.kind{font-size:11px;color:var(--muted);text-transform:uppercase;letter-spacing:.06em}.message details{margin-top:7px;color:var(--muted);font-size:12px}
.side{display:flex;flex-direction:column;gap:16px}.now{min-height:155px}.now-speaker{font-size:22px;font-weight:800;color:var(--gold)}.controls{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}.tech{margin-top:16px}.tech summary{cursor:pointer;font-weight:700}.tech-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:12px}.log,.tree{max-height:330px;overflow:auto;background:#081622;border-radius:10px;padding:10px;font-size:12px;color:var(--muted)}.log-row,.tree-row{padding:5px;border-bottom:1px solid #1d3142}
@media(max-width:900px){.participants{grid-template-columns:1fr 1fr}.workspace{grid-template-columns:1fr}.conversation{max-height:none}.side{display:grid;grid-template-columns:1fr 1fr}}@media(max-width:590px){header,.composer{display:block}.composer-actions{flex-direction:row;margin-top:9px}.participants,.side,.tech-grid{grid-template-columns:1fr}.message{max-width:96%}}
</style></head><body>
<header><div><div class="eyebrow">● Local · source-backed</div><h1>Agent Conference</h1><div class="muted">Meaningful participant messages up front. Technical events stay backstage.</div></div><div id="run-status" class="status">Idle</div></header>
<main>
<section class="panel composer"><textarea id="objective" maxlength="4000" placeholder="What should the agents discuss and solve?"></textarea><div class="composer-actions"><button id="start" class="primary">Start conference</button><button id="cancel" class="danger" disabled>Cancel</button></div><div id="error" class="error">Do not enter passwords, API keys, or other secrets.</div></section>
<section id="participants" class="participants"></section>
<div class="workspace"><section class="panel"><h2>Conference conversation</h2><div id="conversation" class="conversation"><div id="empty" class="empty"><div><strong>No conference yet</strong><p>Enter an objective above. Researcher and Builder contribute first, Reviewer challenges them, and Moderator closes.</p></div></div></div></section>
<aside class="side"><section class="panel now"><h2>Now speaking</h2><div id="now-speaker" class="now-speaker">Nobody yet</div><div id="now-text" class="muted">The transcript remains available if audio is off.</div><div class="controls"><button id="audio">Audio on</button><button id="pause">Pause voice</button></div></section><section class="panel"><h2>Session</h2><div id="provider">Provider: loading…</div><div id="session" class="muted">Waiting for a run.</div></section></aside></div>
<details class="panel tech"><summary>Technical log and delegation tree</summary><div class="tech-grid"><div><h2>Execution events</h2><div id="log" class="log"></div></div><div><h2>Delegation</h2><div id="tree" class="tree"></div></div></div></details>
</main><script>
const token=new URLSearchParams(location.search).get('token');const participants=new Map(),voices=new Map(),speakerMute=new Set(),usedVoices=new Set(),spoken=new Set(),tasks=new Map();let audioOn=true,voicePaused=false,speaking=false,speechQueue=[];
const roles={Researcher:'Facts, assumptions, and uncertainty',Builder:'Concrete implementation approach',Reviewer:'Risks, objections, and validation',Moderator:'Synthesis and next actions'};
function hash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return h>>>0}
function allVoices(){return 'speechSynthesis'in window?[...speechSynthesis.getVoices()].sort((a,b)=>a.name.localeCompare(b.name)):[]}
function chosenVoice(id){const all=allVoices();if(voices.has(id)){const found=all.find(v=>v.name===voices.get(id));if(found)return found;voices.delete(id)}if(!all.length)return null;const pool=id==='Moderator'?all:(all.length>1?all.slice(1):all);let selected=pool[hash(id)%pool.length];for(const v of pool){if(!usedVoices.has(v.name)){selected=v;break}}voices.set(id,selected.name);usedVoices.add(selected.name);return selected}
function voiceSelect(select,id){const current=voices.get(id)||'';select.replaceChildren(new Option('Automatic voice',''));for(const voice of allVoices())select.add(new Option(voice.name,voice.name));select.value=current}
function participantCard(id){if(participants.has(id))return participants.get(id);const card=document.createElement('article');card.className='panel participant';card.dataset.id=id;const name=document.createElement('div'),role=document.createElement('div'),state=document.createElement('div'),row=document.createElement('div'),select=document.createElement('select'),mute=document.createElement('button');name.className='participant-name';name.textContent=id;role.className='participant-role';role.textContent=roles[id]||'Conference participant';state.className='participant-state';state.textContent='Waiting';row.className='voice-row';select.setAttribute('aria-label',`Voice for ${id}`);voiceSelect(select,id);select.onchange=()=>{if(select.value)voices.set(id,select.value);else voices.delete(id)};mute.textContent='Mute';mute.onclick=()=>{speakerMute.has(id)?speakerMute.delete(id):speakerMute.add(id);mute.textContent=speakerMute.has(id)?'Unmute':'Mute'};row.append(select,mute);card.append(name,role,state,row);document.querySelector('#participants').append(card);participants.set(id,card);return card}
for(const id of Object.keys(roles))participantCard(id);
function setAgentState(id,state){const card=participantCard(id);card.querySelector('.participant-state').textContent=state}
function setActive(id,on){const card=participants.get(id);if(card)card.classList.toggle('active',on)}
function pump(){if(speaking||!audioOn||voicePaused||!speechQueue.length||!('speechSynthesis'in window))return;const message=speechQueue.shift();if(speakerMute.has(message.speaker_id)){pump();return}const utterance=new SpeechSynthesisUtterance(message.text),voice=chosenVoice(message.speaker_id);if(voice)utterance.voice=voice;utterance.rate=.92+(hash(message.speaker_id)%17)/100;utterance.pitch=.92+(hash(message.speaker_id+'p')%17)/100;speaking=true;setActive(message.speaker_id,true);document.querySelector('#now-speaker').textContent=message.speaker_id;document.querySelector('#now-text').textContent=message.text;utterance.onend=utterance.onerror=()=>{setActive(message.speaker_id,false);speaking=false;pump()};speechSynthesis.speak(utterance)}
function speak(message){const key=[...message.source_event_ids].sort().join(',');if(spoken.has(key)||!audioOn)return;spoken.add(key);if(speechQueue.length>=24)speechQueue.shift();speechQueue.push(message);pump()}
function addMessage(message){if(document.getElementById('m-'+message.turn_id))return;document.querySelector('#empty')?.remove();const box=document.createElement('article');box.id='m-'+message.turn_id;box.className='message'+(message.message_kind==='decision'?' decision':'');box.innerHTML='<div class="message-head"><span class="speaker"></span><span class="kind"></span></div><div class="body"></div><details><summary>Provenance</summary><div class="provenance"></div></details>';box.querySelector('.speaker').textContent=message.speaker_id;box.querySelector('.kind').textContent=message.message_kind||'statement';box.querySelector('.body').textContent=message.text;box.querySelector('.provenance').textContent=`Sources: ${message.source_event_ids.join(', ')} · ${message.transformation_name}@${message.transformation_version}`;document.querySelector('#conversation').append(box);box.scrollIntoView({block:'nearest'});setAgentState(message.speaker_id,'Contributed');document.querySelector('#now-speaker').textContent=message.speaker_id;document.querySelector('#now-text').textContent=message.text;speak(message)}
function addUser(text){document.querySelector('#empty')?.remove();const box=document.createElement('article');box.className='message user';box.innerHTML='<div class="message-head"><span class="speaker">You</span><span class="kind">objective</span></div><div class="body"></div>';box.querySelector('.body').textContent=text;document.querySelector('#conversation').append(box)}
function technical(e){const row=document.createElement('div');row.className='log-row';row.textContent=`#${e.sequence} ${e.event_type} — ${e.summary}`;const log=document.querySelector('#log');log.append(row);while(log.children.length>200)log.firstChild.remove();if(e.worker_id&&!e.event_type.startsWith('runtime.worker.'))setAgentState(e.worker_id,e.status||e.event_type.split('.').pop());if(e.task_id){const path=e.agent_path||[],old=tasks.get(e.task_id),depth=path.length,label=path.at(-1)||e.worker_id||e.task_id;tasks.set(e.task_id,{id:e.task_id,parent:e.parent_task_id||old?.parent||'',label:!old||depth>=old.depth?label:old.label,depth:Math.max(depth,old?.depth||0),status:e.status||old?.status||'active'});renderTree()}}
function renderTree(){const box=document.querySelector('#tree');box.textContent='';const children=new Map();for(const n of tasks.values()){const p=n.parent||'';if(!children.has(p))children.set(p,[]);children.get(p).push(n)}function walk(parent,depth){for(const n of children.get(parent)||[]){const row=document.createElement('div');row.className='tree-row';row.style.paddingLeft=`${depth*15}px`;row.textContent=`${depth?'↳':'●'} ${n.label} — ${n.status}`;box.append(row);walk(n.id,depth+1)}}walk('',0)}
async function state(){try{const response=await fetch(`/api/state?token=${encodeURIComponent(token)}`,{cache:'no-store'});if(!response.ok)return;const value=await response.json(),c=value.conference;if(!c)return;document.querySelector('#provider').textContent=`Provider: ${c.provider}`;document.querySelector('#session').textContent=c.conference_id?`Conference ${c.conference_id}`:'Waiting for a run.';document.querySelector('#run-status').textContent=c.status[0].toUpperCase()+c.status.slice(1);const busy=['queued','running','cancelling'].includes(c.status);document.querySelector('#start').disabled=busy;document.querySelector('#cancel').disabled=!busy;if(c.status==='completed')for(const card of participants.values())card.querySelector('.participant-state').textContent='Finished';if(c.error)document.querySelector('#error').textContent=c.error}catch(e){document.querySelector('#error').textContent='Local control connection unavailable.'}}
async function command(path,body={}){const response=await fetch(`${path}?token=${encodeURIComponent(token)}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const value=await response.json();if(!response.ok)throw new Error(value.error||'Request failed');return value}
document.querySelector('#start').onclick=async()=>{const objective=document.querySelector('#objective').value.trim(),error=document.querySelector('#error');error.textContent='';if(!objective){error.textContent='Enter an objective first.';return}try{addUser(objective);await command('/api/runs',{objective});document.querySelector('#objective').value='';await state()}catch(e){error.textContent=e.message}};
document.querySelector('#cancel').onclick=async()=>{try{await command('/api/runs/cancel');await state()}catch(e){document.querySelector('#error').textContent=e.message}};
document.querySelector('#audio').onclick=e=>{audioOn=!audioOn;if(!audioOn){speechQueue=[];speaking=false;speechSynthesis.cancel()}e.target.textContent=audioOn?'Audio on':'Audio off'};
document.querySelector('#pause').onclick=e=>{voicePaused=!voicePaused;voicePaused?speechSynthesis.pause():speechSynthesis.resume();e.target.textContent=voicePaused?'Resume voice':'Pause voice'};
if('speechSynthesis'in window)speechSynthesis.onvoiceschanged=()=>document.querySelectorAll('.participant').forEach(card=>voiceSelect(card.querySelector('select'),card.dataset.id));
const es=new EventSource(`/events?token=${encodeURIComponent(token)}`);es.onmessage=frame=>{const payload=JSON.parse(frame.data);technical(payload.event);for(const message of payload.messages)addMessage(message);state()};es.onerror=()=>document.querySelector('#error').textContent='Live connection interrupted; reconnecting…';es.onopen=()=>{const error=document.querySelector('#error');if(error.textContent.startsWith('Live connection'))error.textContent=''};state();setInterval(state,1500);
</script></body></html>"""
